import{_ as e,o as s,c as a,a2 as d}from"./chunks/framework.2Gs1zKBA.js";const k=JSON.parse('{"title":"模型与控制生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/index.md","filePath":"concepts/index.md","lastUpdated":1793694501000}'),i={name:"concepts/index.md"};function n(l,t,r,o,h,c){return s(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="模型与控制生命周期" tabindex="-1">模型与控制生命周期 <a class="header-anchor" href="#模型与控制生命周期" aria-label="Permalink to &quot;模型与控制生命周期&quot;">​</a></h1><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型名</th><th>含义</th></tr></thead><tbody><tr><td><code>A1L</code></td><td>左机械臂</td></tr><tr><td><code>A1R</code></td><td>右机械臂</td></tr></tbody></table><p>角度使用弧度，角速度使用 <code>rad/s</code>，位置使用米，力和力矩分别使用牛顿和牛顿米。</p><p>接口中常见的数据可以按下表区分：</p><table tabindex="0"><thead><tr><th>数据</th><th>典型字段或参数</th><th>单位</th><th>用途</th></tr></thead><tbody><tr><td>关节位置</td><td><code>joints</code>、<code>movej()</code></td><td>rad</td><td>描述 7 个关节的姿态</td></tr><tr><td>关节速度</td><td><code>velocities</code>、<code>speedj()</code></td><td>rad/s</td><td>描述或控制关节运动速度</td></tr><tr><td>TCP 位置</td><td><code>position</code>、<code>get_pose()</code></td><td>m</td><td>描述末端位置</td></tr><tr><td>TCP 姿态</td><td><code>rotation</code>、<code>pose</code></td><td>rad 或旋转矩阵</td><td>描述末端方向</td></tr><tr><td>力与力矩</td><td><code>torques</code>、<code>wrench</code></td><td>N、N·m</td><td>读取反馈或配置力控目标</td></tr></tbody></table><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><ol><li>创建 <code>Arm</code> 并选择唯一后端：<code>channel</code>、<code>backend</code> 或 <code>can_bus</code> 三选一。</li><li>调用 <code>enable()</code> 进入可控状态。</li><li>发送运动或状态查询指令。</li><li>使用 <code>stop()</code> 中断运动，必要时切断电源。</li><li>仅在机械臂已得到可靠支撑时调用 <code>disable()</code>。</li><li><code>close()</code> 关闭通信资源，默认不失能。</li></ol><p>后端的选择决定数据从哪里来，但不改变上层主要运动接口：</p><table tabindex="0"><thead><tr><th>后端</th><th>构造方式</th><th style="text-align:right;">是否连接 CAN</th><th>适合用途</th></tr></thead><tbody><tr><td>MuJoCo</td><td><code>backend=MujocoBackend(...)</code></td><td style="text-align:right;">否</td><td>模型、轨迹和接口验证</td></tr><tr><td>SocketCAN</td><td><code>channel=&quot;can0&quot;</code></td><td style="text-align:right;">是</td><td>真机控制和反馈读取</td></tr><tr><td>自定义后端</td><td><code>backend=...</code></td><td style="text-align:right;">取决于实现</td><td>集成外部控制器或测试环境</td></tr></tbody></table><p>同一段代码在不同后端运行前，仍需重新检查模型、安装方向、负载和安全条件。</p><div class="warning custom-block"><p class="custom-block-title">术语区别</p><ul><li><strong>停止运动</strong>：<code>stop()</code>，尽量减速至静止并保持控制。</li><li><strong>失能</strong>：<code>disable()</code>，电机不再提供维持姿态所需的力矩，机械臂可能下落。</li><li><strong>紧急停止</strong>：<code>emergency_stop()</code> 立即失能所有电机（之后需 <code>enable()</code> 恢复），不应与普通停止混用。</li></ul></div><h3 id="生命周期动作对照" tabindex="-1">生命周期动作对照 <a class="header-anchor" href="#生命周期动作对照" aria-label="Permalink to &quot;生命周期动作对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th style="text-align:right;">是否停止当前运动</th><th style="text-align:right;">是否撤销保持力矩</th><th style="text-align:right;">是否释放通信资源</th><th>典型用途</th></tr></thead><tbody><tr><td><code>stop()</code></td><td style="text-align:right;">是</td><td style="text-align:right;">否</td><td style="text-align:right;">否</td><td>正常中止任务或处理可控异常</td></tr><tr><td><code>disable()</code></td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td style="text-align:right;">否</td><td>已可靠支撑后撤销电机力矩</td></tr><tr><td><code>close()</code></td><td style="text-align:right;">不作为停止流程使用</td><td style="text-align:right;">默认否</td><td style="text-align:right;">是</td><td>释放 SDK/总线资源</td></tr><tr><td><code>close(disable=True)</code></td><td style="text-align:right;">结束时失能</td><td style="text-align:right;">是</td><td style="text-align:right;">是</td><td>已确认支撑条件下关闭会话</td></tr><tr><td><code>emergency_stop()</code></td><td style="text-align:right;">紧急中止</td><td style="text-align:right;">是</td><td style="text-align:right;">取决于后续关闭</td><td>人员或设备立即处于危险状态</td></tr></tbody></table><p>程序退出、浏览器关闭和网络断开都不是现场安全动作。应用应把运动中止、失能和资源释放明确写在不同的分支中，并在异常路径中先处理机械臂状态。</p><h2 id="上下文管理器" tabindex="-1">上下文管理器 <a class="header-anchor" href="#上下文管理器" aria-label="Permalink to &quot;上下文管理器&quot;">​</a></h2><p><code>with Arm(...)</code> 会调用 <code>enable()</code>，退出时关闭通信；它不会默认失能。这一行为用于避免带重力负载的机械臂突然下落。</p><p>因此，推荐把资源释放写在 <code>finally</code> 中，并明确区分三个动作：运动中止使用 <code>stop()</code>，通信资源释放使用 <code>close()</code>，确认机械臂有可靠支撑后才使用 <code>disable()</code>。不要把异常退出、网页关闭或 Python 进程结束当作安全停止流程。</p><h3 id="最小控制骨架" tabindex="-1">最小控制骨架 <a class="header-anchor" href="#最小控制骨架" aria-label="Permalink to &quot;最小控制骨架&quot;">​</a></h3><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> onero_sdk </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Arm, OneroError</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Arm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1R&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">channel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;can0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">try</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    arm.enable()</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 在此发送已经过现场确认的运动目标。</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">except</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OneroError:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    arm.stop()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    raise</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">finally</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # close() 只释放通信；仅在机械臂可靠支撑后才使用 close(disable=True)。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    arm.close()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>该骨架用于说明责任边界，不替代现场急停、断电或上层安全联锁。不同任务还应补充目标验证、超时、状态记录和工具/负载检查。</p>`,21)])])}const g=e(i,[["render",n]]);export{k as __pageData,g as default};
